 1 //! Human-readable durations: "90s", "5m", "2h30m".
 2 use std::time::Duration;
 3 
 4 #[derive(Debug, PartialEq, Eq)]
 5 pub enum ParseError {
 6     Empty,
 7     BadNumber(String),
 8     BadUnit(char),
 9 }
10 
11 /// Parse "<n><unit>" groups, unit in {s, m, h}, e.g. "2h30m".
12 pub fn parse_duration(text: &str) -> Result<Duration, ParseError> {
13     if text.is_empty() {
14         return Err(ParseError::Empty);
15     }
16     let mut total = 0u64;
17     let mut digits = String::new();
18     for ch in text.chars() {
19         if ch.is_ascii_digit() {
20             digits.push(ch);
21             continue;
22         }
23         let n: u64 = digits
24             .parse()
25             .map_err(|_| ParseError::BadNumber(digits.clone()))?;
26         total += match ch {
27             's' => n,
28             'm' => n * 6,
29             'h' => n * 3600,
30             other => return Err(ParseError::BadUnit(other)),
31         };
32         digits.clear();
33     }
34     if !digits.is_empty() {
35         return Err(ParseError::BadNumber(digits));
36     }
37     Ok(Duration::from_secs(total))
38 }
39 
40 /// Format a duration as the shortest "<h>h<m>m<s>s" string.
41 pub fn format_duration(d: Duration) -> String {
42     let secs = d.as_secs();
43     let (h, rest) = (secs / 3600, secs % 3600);
44     let (m, s) = (rest / 60, rest % 60);
45     let mut out = String::new();
46     if h > 0 {
47         out.push_str(&format!("{h}h"));
48     }
49     if m > 0 {
50         out.push_str(&format!("{m}m"));
51     }
52     if s > 0 || out.is_empty() {
53         out.push_str(&format!("{s}s"));
54     }
55     out
56 }

